import java.util.*;

class Solution {
    public int climbStairs(int n) {
        if (n <= 2) return n;
        int a = 1, b = 2;          // ways to reach step i-2 and step i-1
        for (int i = 3; i <= n; i++) {
            int c = a + b;         // last hop was a 1-hop or a 2-hop
            a = b;
            b = c;
        }
        return b;
    }
}

